#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <inttypes.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unicorn/unicorn.h>
#include <unicorn/arm.h>

/* Private v1 wire: generated by the Haskell native-case adapter, independently checked here.
   The MAX_ values that appear in the wire (regions, region bytes, functions, declared stubs,
   total mapped bytes) are the public bounded-native-case contract of schemas/native-case.schema.json
   and Emulation/NativeCase.hs. The expected-events public number is enforced by the schema and
   adapter, not the wire, so the runner does not carry it. MAX_RECORDED_EVENTS is a separate
   engine limit: the count of stub events a case's execution may record. Measured over the
   2738-case SD suite, the largest recorded was 284 events; the 512 capacity provides headroom. */
#define MAX_REGIONS 16
#define MAX_REGION_BYTES (2 * 1024 * 1024)
#define MAX_FUNCTIONS 256
#define MAX_STUBS 32
#define MAX_RECORDED_EVENTS 512
#define MAX_BYTES (4 * 1024 * 1024)
#define LOG_SIZE 64
#define PROVENANCE_SIZE 4096
#define PAGE 4096u
static const int reg_ids[] = {UC_ARM_REG_R0, UC_ARM_REG_R1, UC_ARM_REG_R2,
    UC_ARM_REG_R3, UC_ARM_REG_R4, UC_ARM_REG_R5, UC_ARM_REG_R6, UC_ARM_REG_R7,
    UC_ARM_REG_R8, UC_ARM_REG_R9, UC_ARM_REG_R10, UC_ARM_REG_R11,
    UC_ARM_REG_R12, UC_ARM_REG_SP, UC_ARM_REG_LR, UC_ARM_REG_CPSR, UC_ARM_REG_PC};
static const char *reg_names[] = {"r0", "r1", "r2", "r3", "r4", "r5", "r6",
    "r7", "r8", "r9", "r10", "r11", "r12", "sp", "lr", "cpsr", "pc"};
typedef struct { uint32_t address, size, perms; unsigned char *bytes; } Region;
typedef struct { uint32_t address, size; } Function;
typedef struct { unsigned reg; uint32_t value; } Binding;
typedef struct { uint32_t address; unsigned ni, no; Binding in[15], out[15]; } Stub;
typedef struct { uint32_t pc, instruction; } Trace;
typedef struct { int type, size; uint64_t address, value; } Access;
typedef struct { uint32_t pc, instruction; int type, size; uint64_t address, value; } Provenance;
typedef struct {
    uc_engine *uc; Region regions[MAX_REGIONS]; Function functions[MAX_FUNCTIONS];
    Stub stubs[MAX_STUBS]; unsigned nr, nf, ns; uint32_t regs[17], entry, exit;
    uint64_t budget, wall_ms, instructions, started_ns, elapsed_ns;
    const char *status; uc_err engine_error; uint32_t runtime_version; unsigned current, depth;
    struct { uint32_t ret; unsigned function; } stack[32]; bool returning;
    Trace trace[LOG_SIZE]; Access access[LOG_SIZE]; uint64_t accesses;
    Provenance provenance[PROVENANCE_SIZE]; uint64_t provenance_total;
    unsigned events[MAX_RECORDED_EVENTS], nevents;
} Case;

static bool token(char *buffer, size_t cap)
{
    int c; size_t n = 0;
    do { c = getchar(); } while (c != EOF && (c == ' ' || c == '\n' || c == '\r' || c == '\t'));
    if (c == EOF) return false;
    do {
        if (n + 1 >= cap) return false;
        buffer[n++] = (char)c; c = getchar();
    } while (c != EOF && c != ' ' && c != '\n' && c != '\r' && c != '\t');
    buffer[n] = 0; return true;
}
static bool number(uint64_t *value, unsigned base, uint64_t max)
{
    char b[32], *end = NULL;
    if (!token(b, sizeof b) || b[0] == '+' || b[0] == '-') return false;
    for (size_t i = 0; b[i]; ++i)
        if (!(b[i] >= '0' && b[i] <= '9') && !(base == 16 && b[i] >= 'a' && b[i] <= 'f')) return false;
    errno = 0; unsigned long long v = strtoull(b, &end, base);
    if (errno || !end || *end || v > max) return false;
    *value = v; return true;
}
static bool u32(uint32_t *v) { uint64_t x; if (!number(&x,16,UINT32_MAX)) return false; *v=(uint32_t)x; return true; }
static bool count(unsigned *v, unsigned max) { uint64_t x; if (!number(&x,10,max)) return false; *v=(unsigned)x; return true; }
static int nibble(char c) { return c >= '0' && c <= '9' ? c-'0' : c >= 'a' && c <= 'f' ? c-'a'+10 : -1; }
static bool contains(uint64_t base, uint64_t len, uint64_t address, uint64_t size)
{ return size && address >= base && address <= UINT32_MAX && size <= UINT64_C(0x100000000)-address && address-base <= len && size <= len-(address-base); }
static int region_for(Case *c, uint64_t address, uint64_t size, unsigned perms)
{
    for (unsigned i=0; i<c->nr; ++i)
        if (contains(c->regions[i].address,c->regions[i].size,address,size) && (c->regions[i].perms & perms)==perms) return (int)i;
    return -1;
}
static int function_for(Case *c, uint32_t address)
{ for (unsigned i=0;i<c->nf;++i) if (address>=c->functions[i].address && address<c->functions[i].address+c->functions[i].size) return (int)i; return -1; }
static bool clock_ns(uint64_t *v)
{ struct timespec t; if (clock_gettime(CLOCK_MONOTONIC,&t)) return false; *v=(uint64_t)t.tv_sec*1000000000u+(uint64_t)t.tv_nsec; return true; }
static void fail(Case *c, const char *status)
{
    if (!c->status) c->status=status;
    if (c->uc) { uc_err e=uc_emu_stop(c->uc); if (e!=UC_ERR_OK) { c->status="engine_error"; c->engine_error=e; } }
}
static bool checked(Case *c, uc_err e)
{ if (e==UC_ERR_OK) return true; c->engine_error=e; fail(c,"engine_error"); return false; }
static bool read_reg(Case *c, unsigned reg, uint32_t *value)
{ return checked(c,uc_reg_read(c->uc,reg_ids[reg],value)); }
static bool write_reg(Case *c, unsigned reg, uint32_t value)
{ return checked(c,uc_reg_write(c->uc,reg_ids[reg],&value)); }
static bool condition(unsigned cond,uint32_t f)
{
    bool n=f>>31, z=(f>>30)&1, carry=(f>>29)&1, v=(f>>28)&1;
    switch(cond) {
    case 0:return z; case 1:return !z; case 2:return carry; case 3:return !carry;
    case 4:return n; case 5:return !n; case 6:return v; case 7:return !v;
    case 8:return carry&&!z; case 9:return !carry||z; case 10:return n==v;
    case 11:return n!=v; case 12:return !z&&n==v; case 13:return z||n!=v;
    case 14:return true; default:return false;
    }
}
static void memory_hook(uc_engine *,uc_mem_type,uint64_t,int,int64_t,void *);
/* The admitted PC-relative dispatch: ldr pc,[pc,Rm,LSL#2], pre-indexed, no writeback. */
static bool jump_table_form(uint32_t ins)
{
    unsigned top=(ins>>25)&7, rn=(ins>>16)&15, rd=(ins>>12)&15, rm=ins&15, shift=(ins>>4)&255;
    return top==3 && rd==15 && rn==15 && rm!=15 && (ins&(1u<<20)) && (ins&(1u<<23)) &&
        (ins&(1u<<24)) && !(ins&(1u<<21)) && !(ins&(1u<<22)) && !(shift&1) &&
        ((shift>>1)&3)==0 && ((shift>>3)&31)==2;
}
/* The doubleword transfer space: the extra-load/store words with S set, H free and bit 20 clear, which
   is exactly LDRD (H clear) and STRD (H set) in any addressing mode. */
static bool doubleword_space(uint32_t ins)
{
    return ((ins>>25)&7)==0 && (ins&0xd0u)==0xd0u && !(ins&(1u<<20));
}
/* The admitted doubleword forms: LDRD/STRD pre-indexed with an immediate offset, writeback optional
   when the base is not one of the two transferred registers, or with a register offset and no
   writeback, Rm not the PC and, for LDRD, not one of the pair (the colour stage's
   ldrd r4,r5,[r0,r3]); Rt even with Rt+1 below the PC and Rn not the PC. */
static bool doubleword_form(uint32_t ins)
{
    unsigned rn=(ins>>16)&15, rt=(ins>>12)&15, rm=ins&15;
    bool pre=ins&(1u<<24), imm=ins&(1u<<22), wb=ins&(1u<<21), load=(ins&0x20u)==0;
    if (!doubleword_space(ins) || !pre) return false;
    if (rn==15 || rt%2 || rt==14) return false;
    if (!imm) return !wb && ((ins>>8)&15u)==0 && rm!=15 && !(load && (rm==rt || rm==rt+1));
    return !(wb && (rn==rt || rn==rt+1));
}
/* The admitted register-base dispatch: ldr pc,[Rn,Rm{,shift}], pre-indexed, no writeback,
   word, immediate LSL/LSR/ASR, Rn and Rm not the PC. */
static bool register_dispatch_form(uint32_t ins)
{
    unsigned top=(ins>>25)&7, rn=(ins>>16)&15, rd=(ins>>12)&15, rm=ins&15, shift=(ins>>4)&255;
    return top==3 && rd==15 && rn!=15 && rm!=15 && (ins&(1u<<20)) && (ins&(1u<<24)) &&
        !(ins&(1u<<21)) && !(ins&(1u<<22)) && !(shift&1) && ((shift>>1)&3)!=3;
}
/* The admitted halfword transfer forms: LDRH/STRH with an immediate offset, pre-indexed with optional
   writeback or post-indexed (the compiled hook walk's ldrh r0,[r6],#2), or a pre-indexed register
   offset with writeback optional, and the signed loads LDRSB/LDRSH pre-indexed with no writeback and
   either an immediate offset (the arm consumers sign-extend a mode-table byte) or a register offset
   with no PC index (the develop record builder's ldrsh r3,[r4,r3]). The signed loads' post-indexed and
   writeback encodings, the unprivileged P=0 W=1 forms and the register-offset post-indexed forms stay
   refused. */
static bool halfword_form(uint32_t ins)
{
    unsigned top=(ins>>25)&7, rn=(ins>>16)&15, rd=(ins>>12)&15, rm=ins&15;
    bool pre=ins&(1u<<24), imm=ins&(1u<<22), wb=ins&(1u<<21);
    bool signed_load=(ins&0xd0u)==0xd0u;
    if (top!=0 || rn==15 || rd==15) return false;
    if (!signed_load && (ins&0xf0u)!=0xb0u) return false;
    if (rd==rn && (!pre || wb)) return false;
    if (signed_load) return pre && !wb && (ins&(1u<<20))!=0 && (imm || (((ins>>8)&15u)==0 && rm!=15));
    if (imm) return pre || !wb;
    return pre && ((ins>>8)&15u)==0 && rm!=15;
}
/* The admitted multiply forms: MUL, MLA and MLS, and the long multiplies UMULL and SMULL with RdHi
   distinct from RdLo; none with the S bit or a PC operand. UMLAL/SMLAL, the S-bit forms and the
   signed halfword multiplies stay refused. */
static bool multiply_form(uint32_t ins)
{
    unsigned rd=(ins>>16)&15, ra=(ins>>12)&15, rm=(ins>>8)&15, rn=ins&15;
    if (ins&(1u<<20)) return false;
    if ((ins&0x0fe0f0f0u)==0x00000090u) return rd!=15 && rn!=15 && rm!=15;
    if ((ins&0x0fe000f0u)==0x00200090u || (ins&0x0ff000f0u)==0x00600090u) return rd!=15 && rn!=15 && rm!=15 && ra!=15;
    if ((ins&0x0fe000f0u)==0x00800090u || (ins&0x0fe000f0u)==0x00c00090u) return rd!=15 && ra!=15 && rm!=15 && rn!=15 && rd!=ra;
    return false;
}
/* The admitted bitfield forms: UBFX and SBFX with width-1 + 1 + lsb <= 32, and BFI (Rm != 15) or BFC
   (Rm = 15) with msb >= lsb; no PC operand. Every other word in the bitfield decode space is refused
   at the instruction. */
static bool bitfield_form(uint32_t ins)
{
    unsigned field=(ins>>16)&31, lsb=(ins>>7)&31, rd=(ins>>12)&15, rm=ins&15;
    if (rd==15) return false;
    if ((ins&0x0fe00070u)==0x07e00050u) return rm!=15 && field+1+lsb<=32; /* UBFX, field is width-1 */
    if ((ins&0x0fe00070u)==0x07a00050u) return rm!=15 && field+1+lsb<=32; /* SBFX, field is width-1 */
    if ((ins&0x0fe00070u)==0x07c00010u) return field>=lsb;                /* BFI/BFC, field is msb */
    return false;
}
/* The bitfield decode space: op1 011 with bit 24 set, bits 23-21 from 101, bit 5 clear and bit 4 set.
   It holds the four allocated forms and their three unallocated siblings. */
static bool bitfield_space(uint32_t ins)
{
    return (ins&0x0f000000u)==0x07000000u && ((ins>>21)&7)>=5 && !(ins&0x20u) && (ins&0x10u);
}
/* The admitted extend forms: UXTB, UXTH, SXTB and SXTH with ROR #0/8/16/24 and no PC operand.
   The accumulating and 16-bit variants and PC destinations stay refused. */
static bool extend_form(uint32_t ins)
{
    unsigned op=(ins>>20)&15, rd=(ins>>12)&15, rotate=(ins>>8)&15, rm=ins&15;
    return (ins&0x0f000000u)==0x06000000u && ((ins>>16)&15u)==15u &&
        (op==0xeu||op==0xfu||op==0xau||op==0xbu) && (ins&0xf0u)==0x70u && !(rotate&3u) && rd!=15 && rm!=15;
}
/* CLZ, register-only: the kernel's not-found test compiles to clz/lsr.
   Rd and Rm at the PC stay refused. */
static bool clz_form(uint32_t ins)
{
    return (ins&0x0fff0ff0u)==0x016f0f10u && ((ins>>12)&15)!=15 && (ins&15)!=15;
}
static bool preflight_access(Case *c,uint64_t address,unsigned size,bool write,uint32_t value)
{
    unsigned perm=write?UC_PROT_WRITE:UC_PROT_READ;
    if (address%size || region_for(c,address,size,perm)<0) {
        memory_hook(c->uc,write?UC_MEM_WRITE:UC_MEM_READ,address,(int)size,value,c);
        return false;
    }
    return true;
}
static void tail_transfer(Case *c,uint32_t target);
static bool preflight_dispatch(Case *c,uint64_t address)
{
    if (!preflight_access(c,address,4,false,0)) return false;
    unsigned char bytes[4];
    if (!checked(c,uc_mem_read(c->uc,address,bytes,4))) return false;
    uint32_t target=(uint32_t)bytes[0]|(uint32_t)bytes[1]<<8|(uint32_t)bytes[2]<<16|(uint32_t)bytes[3]<<24;
    if (target&3u) { fail(c,"unsupported_instruction"); return false; }
    tail_transfer(c,target);
    return true;
}
/* Every address computation here is 32-bit: a U=0 offset subtracts modulo 2^32, and only a carry out of
   a U=1 addition is refused as memory_guard. */
static bool preflight_memory(Case *c,uint32_t ins,uint32_t pc)
{
    unsigned top=(ins>>25)&7, rn=(ins>>16)&15, rd=(ins>>12)&15;
    if (top==3) { /* Register-offset byte/word transfers with writeback optional, the PC-relative jump-table
                   dispatch and the register-base load-to-PC dispatch: pre-indexed, immediate LSL/LSR/ASR. */
        bool pre=(ins>>24)&1, up=(ins>>23)&1, byte=(ins>>22)&1;
        bool wb=(ins>>21)&1, load=(ins>>20)&1;
        unsigned rm=ins&15, shift=(ins>>4)&255, type=(shift>>1)&3, amount=(shift>>3)&31;
        if (jump_table_form(ins)) {
            uint32_t index;
            if (!read_reg(c,rm,&index)) return false;
            uint64_t entry=(uint64_t)(pc+8)+((uint64_t)index<<2);
            if (entry>UINT32_MAX) { fail(c,"memory_guard"); return false; }
            return preflight_dispatch(c,entry);
        }
        if (!pre || (shift&1) || type==3 || rn==15 || rm==15 || (rd==15 && !register_dispatch_form(ins)) ||
            (wb && rd==rn)) {
            fail(c,"unsupported_instruction"); return false;
        }
        uint32_t base=pc+8, index, value=pc+12;
        if (!read_reg(c,rm,&index)) return false;
        if (type==0) index = amount ? (index<<amount) : index;
        else if (type==1) index = amount ? (index>>amount) : 0;
        else index = amount ? (uint32_t)((int32_t)index>>amount) : (uint32_t)((int32_t)index>>31);
        if (rn!=15 && !read_reg(c,rn,&base)) return false;
        uint64_t adjusted=up?(uint64_t)base+index:(uint64_t)(base-index);
        if (adjusted>UINT32_MAX) { fail(c,"memory_guard"); return false; }
        if (!load && rd!=15 && !read_reg(c,rd,&value)) return false;
        if (load && rd==15) return preflight_dispatch(c,adjusted);
        return preflight_access(c,adjusted,byte?1:4,!load,value);
    }
    if (doubleword_space(ins)) { /* LDRD/STRD: two consecutive words at the pre-indexed immediate or register-offset address. */
        if (!doubleword_form(ins)) { fail(c,"unsupported_instruction"); return false; }
        unsigned rt=(ins>>12)&15;
        bool up=(ins>>23)&1, load=(ins&0x20u)==0; /* LDRD carries H clear, STRD H set. */
        uint32_t base, value=pc+12, second=pc+12;
        if (!read_reg(c,rn,&base)) return false;
        uint64_t offset=((ins>>4)&0xf0u)|(ins&15);
        if (!(ins&(1u<<22))) { uint32_t index; if (!read_reg(c,ins&15,&index)) return false; offset=index; }
        uint64_t adjusted=up?(uint64_t)base+offset:(uint32_t)(base-(uint32_t)offset);
        if (adjusted>UINT32_MAX) { fail(c,"memory_guard"); return false; }
        if (!load && !read_reg(c,rt,&value)) return false;
        if (!load && !read_reg(c,rt+1,&second)) return false;
        if (!preflight_access(c,adjusted,4,!load,value)) return false;
        return preflight_access(c,adjusted+4,4,!load,second);
    }
    if (top==0 && (ins&0x90u)==0x90u) { /* LDRH/STRH with an immediate offset pre- or post-indexed, or a
                                            pre-indexed register offset. */
        if (!halfword_form(ins)) { fail(c,"unsupported_instruction"); return false; }
        bool pre=ins&(1u<<24), up=(ins>>23)&1, load=(ins>>20)&1, imm=(ins&(1u<<22))!=0;
        unsigned rm=ins&15;
        uint32_t base, value=pc+12;
        uint64_t offset=0;
        if (imm) offset=((ins>>4)&0xf0u)|(ins&15);
        else { uint32_t index; if (!read_reg(c,rm,&index)) return false; offset=index; }
        if (!read_reg(c,rn,&base)) return false;
        uint64_t adjusted=up?(uint64_t)base+offset:(uint32_t)(base-(uint32_t)offset);
        if (adjusted>UINT32_MAX) { fail(c,"memory_guard"); return false; }
        if (!load && !read_reg(c,rd,&value)) return false;
        unsigned width = ((ins&0xf0u)==0xd0u && !(ins&0x20u)) ? 1u : 2u;
        return preflight_access(c,pre?adjusted:(uint64_t)base,width,!load,value);
    }
    if (top==2) { /* Immediate-offset LDR/STR, byte or word. P=0 W=1 is the unprivileged form and stays
                     refused. */
        bool pre=(ins>>24)&1, up=(ins>>23)&1, byte=(ins>>22)&1;
        bool wb=(ins>>21)&1, load=(ins>>20)&1;
        if ((!pre && wb) || (rn==15 && (!pre||wb)) || (rn==rd && (!pre||wb)) || rd==15) { fail(c,"unsupported_instruction"); return false; }
        uint32_t base=pc+8, value=pc+12;
        if (rn!=15 && !read_reg(c,rn,&base)) return false;
        uint64_t offset=ins&4095, adjusted=up?(uint64_t)base+offset:(uint32_t)(base-(uint32_t)offset);
        if (adjusted>UINT32_MAX) { fail(c,"memory_guard"); return false; }
        uint64_t address=pre?adjusted:base;
        if (!load && rd!=15 && !read_reg(c,rd,&value)) return false;
        return preflight_access(c,address,byte?1:4,!load,value);
    }
    if (top==4) { /* LDM/STM: check the complete transfer before any write. An STM with writeback may name
                     its base only as the lowest listed register, which stores the original base value
                     (the 64-bit divide wrapper's push {sp,lr}); LDM with the base listed stays refused. */
        bool pre=(ins>>24)&1, up=(ins>>23)&1, special=(ins>>22)&1;
        bool wb=(ins>>21)&1, load=(ins>>20)&1;
        unsigned list=ins&65535, n=0;
        for(unsigned i=0;i<16;++i) if(list&(1u<<i)) ++n;
        bool base_listed=wb&&(list&(1u<<rn));
        if (!n||rn==15||special||(base_listed&&(load||(list&(0u-list))!=(1u<<rn)))) { fail(c,"unsupported_instruction"); return false; }
        uint32_t base; if(!read_reg(c,rn,&base)) return false;
        if(wb && (up ? (uint64_t)base+n*4>UINT32_MAX : base<n*4)) { fail(c,"memory_guard"); return false; }
        uint64_t below=(uint64_t)n*4-(pre?0:4);
        uint64_t first=up?(uint64_t)base+(pre?4:0):(base>=below?(uint64_t)base-below:UINT64_MAX);
        if(first>UINT32_MAX || !contains(0,UINT64_C(0x100000000),first,(uint64_t)n*4) || first%4 || region_for(c,first,(uint64_t)n*4,load?UC_PROT_READ:UC_PROT_WRITE)<0) {
            memory_hook(c->uc,load?UC_MEM_READ:UC_MEM_WRITE,first,(int)(n*4),0,c); return false;
        }
    }
    return true;
}
/* The call contract for BL and BLX: a stub target records its event and returns without executing
   the transfer; a declared function target is pushed as a tracked call and the engine executes the
   transfer itself. A target that is neither fails the case. */
static void tracked_call(Case *c,uint32_t target,uint32_t ret)
{
    for (unsigned i=0;i<c->ns;++i) if (target==c->stubs[i].address) {
        Stub *s=&c->stubs[i];
        if (c->nevents==MAX_RECORDED_EVENTS) { fail(c,"stub_contract"); return; }
        for (unsigned j=0;j<s->ni;++j) { uint32_t val; if (!read_reg(c,s->in[j].reg,&val)) return; if (val!=s->in[j].value) { fail(c,"stub_contract"); return; } }
        c->events[c->nevents++]=i;
        for (unsigned j=0;j<s->no;++j) if (!write_reg(c,s->out[j].reg,s->out[j].value)) return;
        if (!write_reg(c,14,ret)) return;
        (void)write_reg(c,16,ret);
        return;
    }
    int fn=function_for(c,target);
    if (fn<0 || c->depth==32) { fail(c,"unknown_call"); return; }
    c->stack[c->depth].ret=ret;
    c->stack[c->depth++].function=c->current; c->current=(unsigned)fn;
}
/* In-function targets retain the current function. Declared targets change the current function
   without changing the call frame. Fetch checks refuse other targets. */
static void tail_transfer(Case *c,uint32_t target)
{
    if (contains(c->functions[c->current].address,c->functions[c->current].size,target,4)) return;
    int fn=function_for(c,target);
    if (fn>=0) c->current=(unsigned)fn;
}
static void code_hook(uc_engine *uc,uint64_t address,uint32_t size,void *data)
{
    (void)uc; Case *c=data; uint64_t now;
    if (!clock_ns(&now)) { fail(c,"engine_error"); return; }
    c->elapsed_ns=now-c->started_ns;
    if (c->elapsed_ns>=c->wall_ms*1000000u) { fail(c,"wall_budget"); return; }
    uint32_t cpsr; if (!read_reg(c,15,&cpsr)) return;
    if (cpsr&(1u<<5)) { fail(c,"unsupported_instruction"); return; }
    if (size!=4 || address%4 || region_for(c,address,size,UC_PROT_EXEC)<0) { fail(c,"fetch_guard"); return; }
    if (address==c->exit) { fail(c,c->returning && !c->depth ? "returned" : "unknown_call"); return; }
    if (!contains(c->functions[c->current].address,c->functions[c->current].size,address,size)) { fail(c,"unknown_call"); return; }
    if (c->instructions>=c->budget) { fail(c,"instruction_budget"); return; }
    unsigned char b[4]; if (!checked(c,uc_mem_read(c->uc,address,b,4))) return;
    uint32_t ins=(uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24;
    c->trace[c->instructions%LOG_SIZE]=(Trace){(uint32_t)address,ins}; ++c->instructions;
    unsigned cond=ins>>28;
    if (cond==15) { fail(c,"unsupported_instruction"); return; }
    if (!condition(cond,cpsr)) return;
    if (clz_form(ins)) { /* the R5F model interrupts on CLZ: evaluate it here and skip the fetch */
        unsigned rm=ins&15, rd=(ins>>12)&15; uint32_t rv, n=0;
        if (!read_reg(c,rm,&rv)) return;
        if (rv==0) n=32; else { while (!(rv&0x80000000u)) { rv<<=1; n++; } }
        if (!write_reg(c,rd,n) || !write_reg(c,16,(uint32_t)address+4)) return;
        return;
    }
    if ((ins&0x0fffffffu)==0x012fff1eu) { /* BX LR is the only supported return. */
        uint32_t lr; if (!read_reg(c,14,&lr)) return;
        if (c->depth) {
            if (lr!=c->stack[c->depth-1].ret) { fail(c,"unknown_call"); return; }
            c->current=c->stack[--c->depth].function;
        } else {
            if (lr!=c->exit) { fail(c,"unknown_call"); return; }
            c->returning=true;
        }
        return;
    }
    if ((ins&0x0f000000u)==0x0b000000u) { /* ARM BL immediate. */
        uint32_t immediate=ins&0x00ffffffu;
        int64_t delta=((immediate&0x00800000u)?(int64_t)immediate-0x01000000:(int64_t)immediate)*4;
        int64_t full_target=(int64_t)address+8+delta;
        if(full_target<0 || full_target>UINT32_MAX) fail(c,"unknown_call");
        else tracked_call(c,(uint32_t)full_target,(uint32_t)address+4);
        return;
    }
    if ((ins&0x0ffffff0u)==0x012fff30u) { /* BLX Rm: a tracked indirect call, ARM targets only. */
        unsigned rm=ins&15; uint32_t target;
        if (rm==15) fail(c,"unsupported_instruction");
        else if (!read_reg(c,rm,&target)) return;
        else if (target&3u) fail(c,"unsupported_instruction");
        else tracked_call(c,target,(uint32_t)address+4);
        return;
    }
    if ((ins&0x0f000000u)==0x0a000000u) { /* ARM B immediate. */
        uint32_t immediate=ins&0x00ffffffu;
        int64_t delta=((immediate&0x00800000u)?(int64_t)immediate-0x01000000:(int64_t)immediate)*4;
        int64_t full=(int64_t)address+8+delta;
        if (full<0 || full>UINT32_MAX) { fail(c,"unknown_call"); return; }
        tail_transfer(c,(uint32_t)full);
        return;
    }
    if ((ins&0x0ffffff0u)==0x012fff10u) { /* ARM BX Rm: the register target goes through the same tail
                                            dispatch as B. BX LR returned above; a Thumb, misaligned or
                                            PC target is not admitted. */
        unsigned rm=ins&15; uint32_t target;
        if (rm==15) fail(c,"unsupported_instruction");
        else if (!read_reg(c,rm,&target)) return;
        else if (target&3u) fail(c,"unsupported_instruction"); /* an unaligned or Thumb PC write is unpredictable in ARMv7-R */
        else tail_transfer(c,target);
        return;
    }
    /* Mode switches, SVC/coprocessors and untracked PC writes are excluded. MOVW/MOVT are register-only. */
    unsigned top=(ins>>25)&7, rd=(ins>>12)&15;
    bool movw_movt=(ins&0x0fb00000u)==0x03000000u;
    if (top>=6 ||
        (top<=1 && rd==15) ||
        ((top==2||top==3) && (ins&(1u<<20)) && rd==15 && !jump_table_form(ins) && !register_dispatch_form(ins)) ||
        (top==0 && (ins&0x90u)==0x90u && !halfword_form(ins) && !doubleword_space(ins) && !multiply_form(ins)) || /* SWP and the rest of the extra load/store forms; the doubleword class is decided by doubleword_form in the preflight. */
        /* A32 SDIV/UDIV, which Unicorn's R5F executes and Cortex-R4 lacks. This clause must outlive any
           widening of the load-to-PC and register-offset exclusions that also reject the encoding today. */
        (ins&0x0fd0f0f0u)==0x0710f010u ||
        (top<=1 && ((ins>>21)&15)>=8 && ((ins>>21)&15)<=11 && !(ins&(1u<<20)) && !movw_movt &&
         (top || (ins&0x90u)!=0x90u))) {
        fail(c,"unsupported_instruction"); return;
    }
    /* Ahead of preflight_memory: these encodings fall inside its load/store windows. */
    if (extend_form(ins) || bitfield_form(ins) || multiply_form(ins) || clz_form(ins)) return;
    if (bitfield_space(ins)) { fail(c,"unsupported_instruction"); return; } /* an unconstrained field range, a PC operand or an unallocated sibling */
    (void)preflight_memory(c,ins,(uint32_t)address);
    if (!c->status && top==4 && (ins&(1u<<20)) && (ins&(1u<<15))) { /* LDM with PC is admitted only as a tracked return. */
        unsigned rn=(ins>>16)&15, list=ins&65535, n=0, slot=0;
        bool pre=(ins>>24)&1, up=(ins>>23)&1;
        for (unsigned i=0;i<16;++i) if (list&(1u<<i)) ++n;
        for (unsigned i=0;i<15;++i) if (list&(1u<<i)) ++slot;
        uint32_t base, target;
        if (!read_reg(c,rn,&base)) return;
        uint64_t below=(uint64_t)n*4-(pre?0:4);
        uint64_t first=up?(uint64_t)base+(pre?4:0):(base>=below?(uint64_t)base-below:UINT64_MAX);
        if (first>UINT32_MAX || !checked(c,uc_mem_read(c->uc,first+(uint64_t)slot*4,&target,4))) return;
        if (target!=(c->depth?c->stack[c->depth-1].ret:c->exit)) { fail(c,"unknown_call"); return; }
        if (c->depth) c->current=c->stack[--c->depth].function; else c->returning=true;
    }
}
static void memory_hook(uc_engine *uc,uc_mem_type type,uint64_t address,int size,int64_t value,void *data)
{
    (void)uc; Case *c=data;
    c->access[c->accesses++%LOG_SIZE]=(Access){(int)type,size,address,(uint64_t)value};
    unsigned perm=(type==UC_MEM_WRITE||type==UC_MEM_WRITE_UNMAPPED||type==UC_MEM_WRITE_PROT) ? UC_PROT_WRITE :
        (type==UC_MEM_FETCH||type==UC_MEM_FETCH_UNMAPPED||type==UC_MEM_FETCH_PROT) ? UC_PROT_EXEC : UC_PROT_READ;
    if (size<=0 || (size>1 && address%(unsigned)size) || region_for(c,address,(uint64_t)size,perm)<0) fail(c,perm==UC_PROT_EXEC ? "fetch_guard" : "memory_guard");
    if (!c->status && (type==UC_MEM_READ || type==UC_MEM_WRITE) && size>0 && size<=8 &&
        region_for(c,address,(uint64_t)size,perm)>=0 && c->instructions) {
        uint64_t observed=(uint64_t)value;
        if (type==UC_MEM_READ) {
            unsigned char bytes[8];
            if (!checked(c,uc_mem_read(c->uc,address,bytes,(size_t)size))) return;
            observed=0;
            for (int i=0;i<size;++i) observed|=(uint64_t)bytes[i]<<(8*i);
        }
        Trace *t=&c->trace[(c->instructions-1)%LOG_SIZE];
        uint64_t index=c->provenance_total++;
        if (index<PROVENANCE_SIZE)
            c->provenance[index]=(Provenance){t->pc,t->instruction,(int)type,size,address,observed};
    }
}
static bool invalid_hook(uc_engine *uc,uc_mem_type type,uint64_t address,int size,int64_t value,void *data)
{ memory_hook(uc,type,address,size,value,data); Case *c=data; if (!c->status) fail(c,"memory_guard"); return false; }
static void interrupt_hook(uc_engine *uc,uint32_t number,void *data)
{ (void)uc; (void)number; fail(data,"unsupported_instruction"); }

static bool parse(Case *c)
{
    char word[32];
    if (!token(word,sizeof word)||strcmp(word,"FUJI_NATIVE_V1")||!token(word,sizeof word)||strcmp(word,"cortex-r5f-arm-le")) return false;
    if (!u32(&c->entry)||!u32(&c->exit)||!number(&c->budget,10,4000000)||!number(&c->wall_ms,10,10000)||!c->budget||!c->wall_ms||c->entry%4||c->exit%4||c->entry==c->exit) return false;
    for (unsigned i=0;i<16;++i) if (!u32(&c->regs[i])) return false;
    if ((c->regs[15]&0x0fffffffu)!=0x10 || c->regs[13]%8 || c->regs[14]!=c->exit) return false;
    if (!count(&c->nr,MAX_REGIONS)||!c->nr||!count(&c->nf,MAX_FUNCTIONS)||!c->nf||!count(&c->ns,MAX_STUBS)) return false;
    uint64_t total=0;
    for (unsigned i=0;i<c->nr;++i) {
        Region *r=&c->regions[i]; unsigned p;
        if (!u32(&r->address)||!u32(&r->size)||!r->size||r->size>MAX_REGION_BYTES||!count(&p,7)||(p!=1&&p!=3&&p!=5)||!contains(r->address,r->size,r->address,r->size)) return false;
        /* With the MPU off, the PMSAv7 default map is execute-never from 0x80000000. Ending by 0x7ffffffc
           keeps a fall-through fetch in executable space, where it reports fetch_guard. */
        if (p==5 && (uint64_t)r->address+r->size>0x7ffffffcu) return false;
        r->perms=p; total+=r->size; if (total>MAX_BYTES) return false;
        for (unsigned j=0;j<i;++j) if ((uint64_t)r->address<c->regions[j].address+(uint64_t)c->regions[j].size && (uint64_t)c->regions[j].address<r->address+(uint64_t)r->size) return false;
        char *hex=malloc((size_t)r->size*2+1); r->bytes=malloc(r->size);
        if (!hex||!r->bytes) { free(hex); return false; }
        if (!token(hex,(size_t)r->size*2+1)||strlen(hex)!=(size_t)r->size*2) { free(hex); return false; }
        for (unsigned j=0;j<r->size;++j) { int a=nibble(hex[2*j]),b=nibble(hex[2*j+1]); if (a<0||b<0) { free(hex); return false; } r->bytes[j]=(unsigned char)(a*16+b); }
        free(hex);
    }
    if (region_for(c,c->entry,4,UC_PROT_EXEC)<0||region_for(c,c->exit,4,UC_PROT_EXEC)<0||c->regs[13]<8||region_for(c,c->regs[13]-8,8,UC_PROT_WRITE)<0) return false;
    for (unsigned i=0;i<c->nf;++i) {
        Function *f=&c->functions[i];
        if (!u32(&f->address)||!u32(&f->size)||f->address%4||f->size%4||region_for(c,f->address,f->size,UC_PROT_EXEC)<0||contains(f->address,f->size,c->exit,4)) return false;
        for (unsigned j=0;j<i;++j) if ((uint64_t)f->address<c->functions[j].address+(uint64_t)c->functions[j].size && (uint64_t)c->functions[j].address<f->address+(uint64_t)f->size) return false;
    }
    int entry=function_for(c,c->entry); if (entry<0) return false; c->current=(unsigned)entry;
    for (unsigned i=0;i<c->ns;++i) {
        Stub *s=&c->stubs[i]; if (!u32(&s->address)||s->address%4||s->address==c->exit||!count(&s->ni,15)||!count(&s->no,15)||!s->no) return false;
        for(unsigned j=0;j<c->nf;++j) if(contains(c->functions[j].address,c->functions[j].size,s->address,4)) return false;
        for (unsigned j=0;j<i;++j) if (s->address==c->stubs[j].address) return false;
        for (unsigned k=0;k<2;++k) for (unsigned j=0;j<(k?s->no:s->ni);++j) {
            Binding *b=k?&s->out[j]:&s->in[j]; if (!count(&b->reg,12)||!u32(&b->value)) return false;
            for (unsigned l=0;l<j;++l) if (b->reg==(k?s->out[l].reg:s->in[l].reg)) return false;
        }
    }
    int ch; do { ch=getchar(); } while(ch==' '||ch=='\n'||ch=='\r'||ch=='\t'); return ch==EOF;
}
static bool setup(Case *c)
{
    unsigned major,minor; c->runtime_version=uc_version(&major,&minor);
    const uint32_t header_version=(UC_API_MAJOR<<24)|(UC_API_MINOR<<16)|(UC_API_PATCH<<8)|UC_API_EXTRA;
    if (major!=UC_API_MAJOR||minor!=UC_API_MINOR||c->runtime_version!=header_version||!uc_arch_supported(UC_ARCH_ARM)) { c->status="engine_error"; return false; }
    if (!checked(c,uc_open(UC_ARCH_ARM,UC_MODE_ARM|UC_MODE_LITTLE_ENDIAN,&c->uc))||!checked(c,uc_ctl_set_cpu_model(c->uc,UC_CPU_ARM_CORTEX_R5F))) return false;
    /* Map backing pages once with union permissions; hooks enforce logical bounds. */
    for (unsigned i=0;i<c->nr;++i) {
        Region *r=&c->regions[i]; uint64_t end=(uint64_t)r->address+r->size;
        for (uint64_t page=r->address&~(uint64_t)(PAGE-1);page<end;page+=PAGE) {
            bool previous=false; for (unsigned j=0;j<i;++j) if (page<(uint64_t)c->regions[j].address+c->regions[j].size && page+PAGE>c->regions[j].address) previous=true;
            if (previous) continue;
            unsigned perms=0; for (unsigned j=0;j<c->nr;++j) if (page<(uint64_t)c->regions[j].address+c->regions[j].size && page+PAGE>c->regions[j].address) perms|=c->regions[j].perms;
            if (!checked(c,uc_mem_map(c->uc,page,PAGE,perms))) return false;
        }
        if (!checked(c,uc_mem_write(c->uc,r->address,r->bytes,r->size))) return false;
    }
    /* Select the user register bank before initializing its SP/LR. */
    if (!write_reg(c,15,c->regs[15])) return false;
    for (unsigned i=0;i<15;++i) if (!write_reg(c,i,c->regs[i])) return false;
    if (!write_reg(c,16,c->entry)) return false;
    uc_hook h;
    /* Unicorn's API accepts callback pointers through void*, as documented. */
    if (!checked(c,uc_hook_add(c->uc,&h,UC_HOOK_CODE,(void *)code_hook,c,1,0))||
        !checked(c,uc_hook_add(c->uc,&h,UC_HOOK_MEM_READ|UC_HOOK_MEM_WRITE|UC_HOOK_MEM_FETCH,(void *)memory_hook,c,1,0))||
        !checked(c,uc_hook_add(c->uc,&h,UC_HOOK_MEM_INVALID,(void *)invalid_hook,c,1,0))||
        !checked(c,uc_hook_add(c->uc,&h,UC_HOOK_INTR,(void *)interrupt_hook,c,1,0))) return false;
    return true;
}
static void hex_bytes(const unsigned char *b,unsigned n) { for(unsigned i=0;i<n;++i) printf("%02x",b[i]); }
static void bindings(Binding *b,unsigned n)
{ printf("{"); for(unsigned i=0;i<n;++i) printf("%s\"%s\":\"0x%08" PRIx32 "\"",i?",":"",reg_names[b[i].reg],b[i].value); printf("}"); }
int main(void)
{
    Case c={0};
    if (!parse(&c)) c.status="invalid_case";
    else if (setup(&c)) {
        if (!clock_ns(&c.started_ns)) c.status="engine_error";
        else {
            uc_err e=uc_emu_start(c.uc,c.entry,0,c.wall_ms*1000,0);
            size_t timed_out=0; (void)checked(&c,uc_query(c.uc,UC_QUERY_TIMEOUT,&timed_out));
            if (!c.status) { if (timed_out) c.status="wall_budget"; else if (e!=UC_ERR_OK) { c.engine_error=e; c.status="engine_error"; } else c.status="unknown_call"; }
            else if (e!=UC_ERR_OK) c.engine_error=e; /* Preserve the guard and underlying error. */
            uint64_t now; if (clock_ns(&now)) c.elapsed_ns=now-c.started_ns; else c.status="engine_error";
        }
    }
    if (!c.status) c.status="engine_error";
    unsigned char *final[MAX_REGIONS]={0};
    if (c.uc) {
        for(unsigned i=0;i<17;++i) if (!read_reg(&c,i,&c.regs[i])) break;
        for(unsigned i=0;i<c.nr;++i) { final[i]=malloc(c.regions[i].size); if(!final[i]) { c.status="engine_error"; break; } if(!checked(&c,uc_mem_read(c.uc,c.regions[i].address,final[i],c.regions[i].size))) { free(final[i]); final[i]=NULL; break; } }
        uc_err e=uc_close(c.uc); c.uc=NULL; if(e!=UC_ERR_OK) { c.status="engine_error"; c.engine_error=e; }
    }
    printf("{\"wire_version\":1,\"status\":\"%s\",\"unicorn_version\":\"0x%08" PRIx32 "\",\"unicorn_error\":%u,\"instructions\":\"%" PRIu64 "\",\"elapsed_ns\":\"%" PRIu64 "\",\"registers\":{",c.status,c.runtime_version,(unsigned)c.engine_error,c.instructions,c.elapsed_ns);
    for(unsigned i=0;i<17;++i) printf("%s\"%s\":\"0x%08" PRIx32 "\"",i?",":"",reg_names[i],c.regs[i]);
    printf("},\"memory\":["); for(unsigned i=0;i<c.nr;++i) { printf("%s{\"address\":\"0x%08" PRIx32 "\",\"bytes\":",i?",":"",c.regions[i].address); if(final[i]) { printf("\""); hex_bytes(final[i],c.regions[i].size); printf("\""); } else printf("null"); printf("}"); }
    printf("],\"events\":["); for(unsigned i=0;i<c.nevents;++i) { Stub *s=&c.stubs[c.events[i]]; printf("%s{\"address\":\"0x%08" PRIx32 "\",\"inputs\":",i?",":"",s->address); bindings(s->in,s->ni); printf(",\"outputs\":"); bindings(s->out,s->no); printf("}"); }
    printf("],\"trace_total\":\"%" PRIu64 "\",\"trace\":[",c.instructions);
    uint64_t first=c.instructions>LOG_SIZE?c.instructions-LOG_SIZE:0;
    for(uint64_t i=first;i<c.instructions;++i) { Trace *t=&c.trace[i%LOG_SIZE]; printf("%s{\"pc\":\"0x%08" PRIx32 "\",\"instruction\":\"0x%08" PRIx32 "\"}",i>first?",":"",t->pc,t->instruction); }
    printf("],\"access_total\":\"%" PRIu64 "\",\"accesses\":[",c.accesses); first=c.accesses>LOG_SIZE?c.accesses-LOG_SIZE:0;
    for(uint64_t i=first;i<c.accesses;++i) { Access *a=&c.access[i%LOG_SIZE]; printf("%s{\"type\":%d,\"address\":\"0x%08" PRIx64 "\",\"size\":%d,\"value\":\"0x%016" PRIx64 "\"}",i>first?",":"",a->type,a->address,a->size,a->value); }
    printf("],\"memory_provenance_total\":\"%" PRIu64 "\",\"memory_provenance\":[",c.provenance_total);
    uint64_t kept=c.provenance_total<PROVENANCE_SIZE?c.provenance_total:PROVENANCE_SIZE;
    for(uint64_t i=0;i<kept;++i) {
        Provenance *p=&c.provenance[i];
        printf("%s{\"pc\":\"0x%08" PRIx32 "\",\"instruction\":\"0x%08" PRIx32 "\",\"kind\":\"%s\",\"address\":\"0x%08" PRIx64 "\",\"size\":%d,\"value\":\"0x%016" PRIx64 "\"}",i?",":"",p->pc,p->instruction,p->type==UC_MEM_WRITE?"write":"read",p->address,p->size,p->value);
    }
    printf("]}\n");
    for(unsigned i=0;i<c.nr;++i) { free(c.regions[i].bytes); free(final[i]); }
    return !strcmp(c.status,"returned")?0:1;
}
